import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

/**
 * An update that a SHACL repository rejects (C13) shows which data violates which constraint, not the name of the
 * exception class that carried the report.
 */
class UpdateServletShaclTest {

	private static final ObjectMapper JSON_MAPPER = new ObjectMapper();

	private static final String UPDATE = "PREFIX ex: <http://example.org/> INSERT DATA { ex:alice ex:age \"abc\" }";

	private static final String REPORT = """
			@prefix sh: <http://www.w3.org/ns/shacl#> .
			@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
			[] a sh:ValidationReport ; sh:conforms false ;
			  sh:result [ a sh:ValidationResult ; sh:focusNode <http://example.org/alice> ;
			      sh:resultPath <http://example.org/age> ; sh:value "abc" ; sh:resultSeverity sh:Violation ;
			      sh:sourceConstraintComponent sh:DatatypeConstraintComponent ; sh:sourceShape _:age ] .
			_:age a sh:PropertyShape ; sh:path <http://example.org/age> ; sh:datatype xsd:integer .
			""";

	@Test
	void aShaclValidationFailureIsShownAsAReadableSummary() throws Exception {
		Repository repository = mock(Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		Update update = mock(Update.class);
		when(repository.getConnection()).thenReturn(connection);
		when(connection.prepareUpdate(QueryLanguage.SPARQL, UPDATE)).thenReturn(update);
		when(connection.getNamespaces()).thenAnswer(invocation -> namespaces());
		doThrow(new RepositoryException(
				new RemoteShaclValidationException(new StringReader(REPORT), "", RDFFormat.TURTLE)))
						.when(update)
						.execute();
		UpdateServlet servlet = new UpdateServlet();
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.init(TestServletConfig.withParams("update", "cookie-max-age", "300"));
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/update");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		request.addParameter("update", UPDATE);
		MockHttpServletResponse response = new MockHttpServletResponse();
		try {
			servlet.service(request, response);
		} finally {
			servlet.destroy();
		}

		String message = column(records(response), "error-message");
		assertThat(message).isEqualTo("""
				SHACL validation failed with 1 violation:
				- ex:alice, ex:age: value "abc": expected datatype xsd:integer""")
				.doesNotContain("RemoteShaclValidationException");
		assertThat(column(records(response), "update")).isEqualTo(UPDATE);
	}

	private static RepositoryResult<Namespace> namespaces() {
		List<Namespace> namespaces = List.of(new SimpleNamespace("ex", "http://example.org/"));
		return new RepositoryResult<>(new CloseableIteratorIteration<>(namespaces.iterator()));
	}

	private static List<JsonNode> records(MockHttpServletResponse response) throws Exception {
		return response.getContentAsString()
				.lines()
				.filter(line -> !line.isBlank())
				.map(JSON_MAPPER::readTree)
				.toList();
	}

	/** The value of a column of the first row. */
	private static String column(List<JsonNode> records, String name) {
		List<String> vars = new ArrayList<>();
		records.stream()
				.filter(record -> "vars".equals(record.path("type").asText()))
				.forEach(record -> record.path("values").forEach(value -> vars.add(value.asText())));
		int column = vars.indexOf(name);
		assertThat(column).as("%s column in %s", name, vars).isGreaterThanOrEqualTo(0);
		return records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.map(record -> record.path("values").get(0).get(column).path("value").asText())
				.findFirst()
				.orElse(null);
	}
}
